// pubspec.yaml: file_picker: ^8.0.0
import 'package:file_picker/file_picker.dart';

// ────── Pick one PDF ──────
Future<PlatformFile?> pickPdf() async {
  final result = await FilePicker.platform.pickFiles(
    type: FileType.custom,
    allowedExtensions: ['pdf'],
  );
  if (result == null || result.files.isEmpty) return null;
  return result.files.first;
}

// ────── Multi-select ──────
Future<List<PlatformFile>> pickDocs() async {
  final r = await FilePicker.platform.pickFiles(
    type: FileType.custom,
    allowedExtensions: ['pdf', 'docx', 'xlsx'],
    allowMultiple: true,
    withData: kIsWeb,     // Web needs bytes; mobile use path
  );
  return r?.files ?? [];
}

// ────── Upload single file via Dio ──────
Future<void> upload(PlatformFile f) async {
  final MultipartFile mpf = kIsWeb
    ? MultipartFile.fromBytes(f.bytes!, filename: f.name)
    : await MultipartFile.fromFile(f.path!, filename: f.name);
  await dio.post('/documents', data: FormData.fromMap({'file': mpf}));
}

